begin;
select no_plan();
update public.plans set prova_monthly_exams=null,prova_scenarios=true where code='free';
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003001','scope-a@test.local'),('00000000-0000-4000-8000-000000003002','scope-b@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000003001','A','00000000-0000-4000-8000-000000003001'),('10000000-0000-4000-8000-000000003002','B','00000000-0000-4000-8000-000000003002');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000003001','00000000-0000-4000-8000-000000003001'),('10000000-0000-4000-8000-000000003002','00000000-0000-4000-8000-000000003002');
insert into public.children(id,family_id,name) values('20000000-0000-4000-8000-000000003001','10000000-0000-4000-8000-000000003001','A child'),('20000000-0000-4000-8000-000000003002','10000000-0000-4000-8000-000000003002','B child');
insert into public.question_bank(id,family_id,grade,subject,topic,kind,difficulty,stem) values
('30000000-0000-4000-8000-000000003001','10000000-0000-4000-8000-000000003001',5,'Fen','Işık','open_ended','orta','A private question'),
('30000000-0000-4000-8000-000000003002','10000000-0000-4000-8000-000000003002',5,'Fen','Işık','open_ended','orta','B private question'),
('30000000-0000-4000-8000-000000003003',null,5,'Fen','Işık','open_ended','orta','Shared question');
insert into public.exam_blueprints(id,family_id,grade,subject,name) values('40000000-0000-4000-8000-000000003002','10000000-0000-4000-8000-000000003002',5,'Fen','B private scenario');
insert into public.learning_sources(id,family_id,uploaded_by,kind,name,mime,bytes,sha256,object_path,status,width,height,storage_consent) values('80000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000003001','00000000-0000-4000-8000-000000003001','question_image','triangle.png','image/png',100,repeat('a',64),'notebook-test/triangle','ready',600,360,'private-storage-v1');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003001","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003001","role":"parent"}}',true);

-- Finish authoring before assignment freezes the question and its images.
select public.attach_question_source('30000000-0000-4000-8000-000000003001','80000000-0000-4000-8000-000000000002','ABC triangle');
insert into public.exams(id,family_id,child_id,title,subject,grade,question_ids,status) values('50000000-0000-4000-8000-000000003001','10000000-0000-4000-8000-000000003001','20000000-0000-4000-8000-000000003001','Receipt practice','Fen',5,array['30000000-0000-4000-8000-000000003001']::uuid[],'assigned');
select set_config('test.answer_attempt',(public.start_exam_attempt('50000000-0000-4000-8000-000000003001')).id::text,true);

select set_config('test.doc','{"version":1,"width":1000,"height":1400,"elements":[{"id":"70000000-0000-4000-8000-000000000001","type":"stroke","color":"#201951","size":4,"points":[[20,30],[80,90]]}]}',true);

select public.submit_exam_answer_v3('60000000-0000-4000-8000-000000003001',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,null,null,current_setting('test.doc')::jsonb);
select set_config('test.hash',(public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')->>'answer_hash'),true);
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003002',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,current_setting('test.hash'),90::smallint,'A note',current_setting('test.doc')::jsonb)$$,'P0001','attempt_not_finished','cannot grade an unfinished attempt');
select public.finish_exam_attempt(current_setting('test.answer_attempt')::uuid);
select lives_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003002',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,current_setting('test.hash'),90::smallint,'A note',current_setting('test.doc')::jsonb)$$,'save score, feedback and separate ink atomically');
select is((select answer_document from public.exam_answers where attempt_id=current_setting('test.answer_attempt')::uuid),current_setting('test.doc')::jsonb,'parent marks never replace child ink');
select is((select review_document from public.exam_answers where attempt_id=current_setting('test.answer_attempt')::uuid),current_setting('test.doc')::jsonb,'parent ink stored separately');
select is((public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')->>'answer_hash'),current_setting('test.hash'),'grading does not alter answer fingerprint');
select set_config('test.review_revision',(public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')->>'revision'),true);
select is(public.save_answer_review('60000000-0000-4000-8000-000000003002',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,current_setting('test.hash'),90::smallint,'A note',current_setting('test.doc')::jsonb),current_setting('test.review_revision')::int,'lost response repeats original receipt');
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003003',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,current_setting('test.hash'),10::smallint,'Overwrite',null)$$,'P0001','review_changed','second parent cannot overwrite stale revision');
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003002',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',0,current_setting('test.hash'),10::smallint,'Changed payload',null)$$,'P0001','request_conflict','receipt cannot change payload');
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003004',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',current_setting('test.review_revision')::int,'bad-hash',90::smallint,'A note',null)$$,'P0001','answer_changed','rejects changed child answer');
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003004',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',current_setting('test.review_revision')::int,current_setting('test.hash'),90::smallint,'A note',null,'90000000-0000-4000-8000-000000003004')$$,'P0001','review_ai_mismatch','rejects forged suggestion');
select throws_ok($$select public.save_answer_review('60000000-0000-4000-8000-000000003004',current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',current_setting('test.review_revision')::int,current_setting('test.hash'),101::smallint,'A note',null)$$,'P0001','invalid_score','rejects invalid score atomically');
select is((public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')->>'revision'),current_setting('test.review_revision'),'failed save does not consume revision');
select ok(not gina.valid_review_document('{"version":1,"width":1000,"height":1400,"elements":[{"id":"70000000-0000-4000-8000-000000000002","type":"source","sourceId":"80000000-0000-4000-8000-000000000002","questionId":"30000000-0000-4000-8000-000000003001","x":0,"y":0,"width":200,"height":200,"crop":{"x":0,"y":0,"width":1,"height":1},"alt":"source"}]}'),'parent layer cannot inject source references');
select public.score_open_answer(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',80::smallint,'Legacy edit');
select ok((public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')->>'revision')::int>current_setting('test.review_revision')::int,'legacy grading also advances review revision');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003002","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003002","role":"parent"}}',true);
select throws_ok($$select public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')$$,'P0001','attempt_not_found','other family cannot read review');
select is(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid),'[]'::jsonb,'other family cannot read published child feedback');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003001","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003001","role":"device","child_id":"20000000-0000-4000-8000-000000003001"}}',true);
select throws_ok($$select public.get_answer_review(current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001')$$,'42501','forbidden','child cannot open parent assessment draft');
select ok(not has_function_privilege('anon','public.save_answer_review(uuid,uuid,uuid,int,text,smallint,text,jsonb,uuid)','execute'),'anonymous cannot write review');
select ok(not has_table_privilege('authenticated','public.answer_review_suggestions','INSERT'),'client cannot forge AI suggestions');
reset role;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000003004',null);
insert into public.children(id,family_id,name) values('20000000-0000-4000-8000-000000003004','10000000-0000-4000-8000-000000003001','Sibling');
insert into public.devices(id,family_id,auth_user_id,active_child_id) values('90000000-0000-4000-8000-000000003004','10000000-0000-4000-8000-000000003001','00000000-0000-4000-8000-000000003004','20000000-0000-4000-8000-000000003001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003004","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003001","role":"device","device_id":"90000000-0000-4000-8000-000000003004","child_id":"20000000-0000-4000-8000-000000003001"}}',true);
select is(jsonb_array_length(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid)),1,'paired child sees own published review');
select is(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid)->0->'answer_document',current_setting('test.doc')::jsonb,'child receives unchanged original beside notes');
select ok(not (public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid)->0 ? 'expected_answer'),'child feedback does not leak answer key');
select throws_ok($$select public.save_answer_review(gen_random_uuid(),current_setting('test.answer_attempt')::uuid,'30000000-0000-4000-8000-000000003001',1,current_setting('test.hash'),100::smallint,'forged',null)$$,'42501','forbidden','real paired child cannot grade');
reset role;
update public.devices set active_child_id='20000000-0000-4000-8000-000000003004' where id='90000000-0000-4000-8000-000000003004';
set local role authenticated;
select is(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid),'[]'::jsonb,'stale child device token denied after switch');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003004","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003001","role":"device","device_id":"90000000-0000-4000-8000-000000003004","child_id":"20000000-0000-4000-8000-000000003004"}}',true);
select is(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid),'[]'::jsonb,'sibling on same tablet cannot read review');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000003001","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000003001","role":"parent"}}',true);
insert into public.question_bank(id,family_id,grade,subject,topic,kind,difficulty,stem,choices,correct_key) values('30000000-0000-4000-8000-000000003005','10000000-0000-4000-8000-000000003001',5,'Fen','Işık','multiple_choice','orta','Choose the right answer','[{"key":"A","text":"a"},{"key":"B","text":"b"}]','A');
insert into public.exams(id,family_id,child_id,title,subject,grade,question_ids,status) values('50000000-0000-4000-8000-000000003005','10000000-0000-4000-8000-000000003001','20000000-0000-4000-8000-000000003001','MC review','Fen',5,array['30000000-0000-4000-8000-000000003005']::uuid[],'assigned');
select set_config('test.mc_attempt',(public.start_exam_attempt('50000000-0000-4000-8000-000000003005')).id::text,true);
select public.submit_exam_answer_v3(gen_random_uuid(),current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005',0,'A',null,null);
select public.finish_exam_attempt(current_setting('test.mc_attempt')::uuid);
select set_config('test.mc_hash',public.get_answer_review(current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005')->>'answer_hash',true);
select set_config('test.mc_revision',public.get_answer_review(current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005')->>'revision',true);
select set_config('test.mc_score',(select coalesce(score::text,'null') from public.exam_answers where attempt_id=current_setting('test.mc_attempt')::uuid),true);
select lives_ok($$select public.save_answer_review(gen_random_uuid(),current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005',current_setting('test.mc_revision')::int,current_setting('test.mc_hash'),null,'Well done',current_setting('test.doc')::jsonb)$$,'MC feedback saves without manual score');
select is((select coalesce(score::text,'null') from public.exam_answers where attempt_id=current_setting('test.mc_attempt')::uuid),current_setting('test.mc_score'),'MC computed score preserved');
select is((select answer_key from public.exam_answers where attempt_id=current_setting('test.mc_attempt')::uuid),'A','MC answer remains unchanged');
select is(jsonb_array_length(public.get_child_answer_reviews(current_setting('test.mc_attempt')::uuid)),1,'MC published feedback visible');
select ok(not has_table_privilege('authenticated','public.answer_review_consents','INSERT'),'client cannot forge durable AI consent');
select public.save_answer_review(gen_random_uuid(),current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005',(public.get_answer_review(current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005')->>'revision')::int,current_setting('test.mc_hash'),null,'Feedback without ink','{"version":1,"width":1000,"height":1400,"elements":[]}');
select is(public.get_child_answer_reviews(current_setting('test.mc_attempt')::uuid)->0->'document','null'::jsonb,'text-only feedback never renders an empty notebook');
select public.save_answer_review(gen_random_uuid(),current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005',(public.get_answer_review(current_setting('test.mc_attempt')::uuid,'30000000-0000-4000-8000-000000003005')->>'revision')::int,current_setting('test.mc_hash'),null,'','{"version":1,"width":1000,"height":1400,"elements":[]}');
select is(public.get_child_answer_reviews(current_setting('test.mc_attempt')::uuid),'[]'::jsonb,'empty review never shows a blank feedback card');
reset role;
insert into public.library_collections(id,title,grade,subject,curriculum_version,status) values('40000000-0000-4000-8000-000000003006','Review embargo test',5,'Fen','test','published');
insert into public.group_exams(id,title,collection_id,grade,subject,curriculum_version,creation_intent,version_hash,starts_at,ends_at,duration_minutes,plans) values('60000000-0000-4000-8000-000000003006','Review embargo test','40000000-0000-4000-8000-000000003006',5,'Fen','test','{}','test',now()-interval '1 hour',now()+interval '1 hour',30,array['free']::public.plan_code[]);
insert into public.group_exam_entries(group_id,family_id,child_id,exam_id,alias,consent_version) values('60000000-0000-4000-8000-000000003006','10000000-0000-4000-8000-000000003001','20000000-0000-4000-8000-000000003001','50000000-0000-4000-8000-000000003001','Review child','test');
set local role authenticated;
select is(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid),'[]'::jsonb,'shared exam feedback embargo applies before end time');
reset role;
update public.group_exams set ends_at=now()-interval '1 minute' where id='60000000-0000-4000-8000-000000003006';
set local role authenticated;
select is(jsonb_array_length(public.get_child_answer_reviews(current_setting('test.answer_attempt')::uuid)),1,'shared exam feedback appears after window ends');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000003001'; set constraints all immediate;$$,'account deletion removes review layer');
select * from finish(); rollback;
